ALTER TABLE accounting_entries ADD COLUMN third_party_type ENUM('CUSTOMER','SUPPLIER','EMPLOYEE','OTHER') NULL AFTER metadata, ADD COLUMN third_party_id VARCHAR(100) NULL AFTER third_party_type, ADD COLUMN third_party_name VARCHAR(255) NULL AFTER third_party_id, ADD KEY idx_accounting_entry_third_party(third_party_type,third_party_id,accounting_date,id);

CREATE TABLE accounting_control_runs(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, scope_type ENUM('GLOBAL','CONCESSION','AGENCY','PERIOD','FISCAL_YEAR') NOT NULL, scope_id BIGINT UNSIGNED NULL, executed_by BIGINT UNSIGNED NOT NULL, started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME NULL, status ENUM('RUNNING','PASS','WARNING','FAIL') NOT NULL DEFAULT 'RUNNING', anomaly_count INT UNSIGNED NOT NULL DEFAULT 0, summary JSON NULL, KEY idx_accounting_control_scope(scope_type,scope_id,started_at), CONSTRAINT fk_accounting_control_actor FOREIGN KEY(executed_by) REFERENCES users(id)
);
CREATE TABLE accounting_control_anomalies(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, run_id BIGINT UNSIGNED NOT NULL, control_code VARCHAR(80) NOT NULL, severity ENUM('INFO','WARNING','ERROR','BLOCKING') NOT NULL, entity_type VARCHAR(80) NULL, entity_id BIGINT UNSIGNED NULL, reference VARCHAR(190) NULL, message VARCHAR(1000) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_accounting_anomaly_run(run_id,severity,id), CONSTRAINT fk_accounting_anomaly_run FOREIGN KEY(run_id) REFERENCES accounting_control_runs(id) ON DELETE RESTRICT
);
CREATE TABLE accounting_closures(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, closure_type ENUM('PERIOD','FISCAL_YEAR') NOT NULL, period_id BIGINT UNSIGNED NULL, fiscal_year_id BIGINT UNSIGNED NOT NULL, status ENUM('PREPARED','CLOSED','REOPENED','BLOCKED') NOT NULL, control_run_id BIGINT UNSIGNED NULL, reason VARCHAR(1000) NULL, prepared_by BIGINT UNSIGNED NOT NULL, prepared_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, closed_by BIGINT UNSIGNED NULL, closed_at DATETIME NULL, reopened_by BIGINT UNSIGNED NULL, reopened_at DATETIME NULL, version INT UNSIGNED NOT NULL DEFAULT 1, UNIQUE KEY uq_accounting_closure_period(period_id), KEY idx_accounting_closure_year(fiscal_year_id,status), CONSTRAINT chk_accounting_closure_target CHECK((closure_type='PERIOD' AND period_id IS NOT NULL) OR closure_type='FISCAL_YEAR'), CONSTRAINT fk_accounting_closure_period FOREIGN KEY(period_id) REFERENCES accounting_periods(id), CONSTRAINT fk_accounting_closure_year FOREIGN KEY(fiscal_year_id) REFERENCES accounting_fiscal_years(id), CONSTRAINT fk_accounting_closure_control FOREIGN KEY(control_run_id) REFERENCES accounting_control_runs(id), CONSTRAINT fk_accounting_closure_preparer FOREIGN KEY(prepared_by) REFERENCES users(id), CONSTRAINT fk_accounting_closure_closer FOREIGN KEY(closed_by) REFERENCES users(id), CONSTRAINT fk_accounting_closure_reopener FOREIGN KEY(reopened_by) REFERENCES users(id)
);
CREATE TABLE accounting_carryforward_runs(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, source_fiscal_year_id BIGINT UNSIGNED NOT NULL, destination_fiscal_year_id BIGINT UNSIGNED NOT NULL, status ENUM('PREPARED','BLOCKED','POSTED','CANCELLED') NOT NULL DEFAULT 'PREPARED', balances JSON NOT NULL, blocking_reason VARCHAR(1000) NULL, accounting_entry_id BIGINT UNSIGNED NULL, prepared_by BIGINT UNSIGNED NOT NULL, prepared_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, posted_by BIGINT UNSIGNED NULL, posted_at DATETIME NULL, UNIQUE KEY uq_accounting_carryforward(source_fiscal_year_id,destination_fiscal_year_id), CONSTRAINT fk_accounting_carryforward_source FOREIGN KEY(source_fiscal_year_id) REFERENCES accounting_fiscal_years(id), CONSTRAINT fk_accounting_carryforward_destination FOREIGN KEY(destination_fiscal_year_id) REFERENCES accounting_fiscal_years(id), CONSTRAINT fk_accounting_carryforward_entry FOREIGN KEY(accounting_entry_id) REFERENCES accounting_entries(id), CONSTRAINT fk_accounting_carryforward_preparer FOREIGN KEY(prepared_by) REFERENCES users(id), CONSTRAINT fk_accounting_carryforward_poster FOREIGN KEY(posted_by) REFERENCES users(id)
);
CREATE TABLE accounting_statement_templates(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, statement_type ENUM('BALANCE_SHEET','INCOME_STATEMENT','CASH_FLOW','NOTES') NOT NULL, reference_source VARCHAR(500) NULL, validation_status ENUM('DRAFT','TO_VERIFY','VALIDATED') NOT NULL DEFAULT 'DRAFT', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_by BIGINT UNSIGNED NOT NULL, validated_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_accounting_template_creator FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT fk_accounting_template_validator FOREIGN KEY(validated_by) REFERENCES users(id)
);
CREATE TABLE accounting_statement_mappings(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, template_id BIGINT UNSIGNED NOT NULL, line_code VARCHAR(60) NOT NULL, line_label VARCHAR(255) NOT NULL, account_prefix VARCHAR(20) NOT NULL, balance_side ENUM('NET','DEBIT','CREDIT') NOT NULL DEFAULT 'NET', display_order INT UNSIGNED NOT NULL, UNIQUE KEY uq_accounting_statement_line(template_id,line_code,account_prefix), CONSTRAINT fk_accounting_statement_mapping_template FOREIGN KEY(template_id) REFERENCES accounting_statement_templates(id) ON DELETE RESTRICT
);
CREATE TABLE accounting_statement_runs(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, template_id BIGINT UNSIGNED NOT NULL, fiscal_year_id BIGINT UNSIGNED NOT NULL, agency_id BIGINT UNSIGNED NULL, status ENUM('PREPARATORY','TO_VERIFY','VALIDATED') NOT NULL DEFAULT 'PREPARATORY', data JSON NOT NULL, generated_by BIGINT UNSIGNED NOT NULL, generated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, validated_by BIGINT UNSIGNED NULL, validated_at DATETIME NULL, KEY idx_accounting_statement_run(template_id,fiscal_year_id,agency_id,generated_at), CONSTRAINT fk_accounting_statement_run_template FOREIGN KEY(template_id) REFERENCES accounting_statement_templates(id), CONSTRAINT fk_accounting_statement_run_year FOREIGN KEY(fiscal_year_id) REFERENCES accounting_fiscal_years(id), CONSTRAINT fk_accounting_statement_run_agency FOREIGN KEY(agency_id) REFERENCES agencies(id), CONSTRAINT fk_accounting_statement_run_generator FOREIGN KEY(generated_by) REFERENCES users(id), CONSTRAINT fk_accounting_statement_run_validator FOREIGN KEY(validated_by) REFERENCES users(id)
);
CREATE TABLE accounting_exchange_profiles(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(60) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, target_product VARCHAR(160) NOT NULL, target_version VARCHAR(80) NULL, direction ENUM('EXPORT','IMPORT','BOTH') NOT NULL, format_code VARCHAR(60) NOT NULL, encoding_name VARCHAR(40) NOT NULL DEFAULT 'UTF-8', delimiter_char CHAR(1) NULL, configuration JSON NOT NULL, validation_status ENUM('DRAFT','TO_VERIFY','VALIDATED') NOT NULL DEFAULT 'DRAFT', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_by BIGINT UNSIGNED NOT NULL, validated_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_accounting_exchange_creator FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT fk_accounting_exchange_validator FOREIGN KEY(validated_by) REFERENCES users(id)
);
CREATE TABLE accounting_exchange_runs(
 id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, profile_id BIGINT UNSIGNED NULL, direction ENUM('EXPORT','IMPORT') NOT NULL, fiscal_year_id BIGINT UNSIGNED NOT NULL, period_id BIGINT UNSIGNED NULL, journal_id BIGINT UNSIGNED NULL, agency_id BIGINT UNSIGNED NULL, status ENUM('PREVIEW','COMPLETED','REJECTED','FAILED') NOT NULL, file_name VARCHAR(255) NULL, checksum CHAR(64) NULL, row_count INT UNSIGNED NOT NULL DEFAULT 0, error_message VARCHAR(1000) NULL, executed_by BIGINT UNSIGNED NOT NULL, executed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_accounting_exchange_history(direction,executed_at,id), CONSTRAINT fk_accounting_exchange_profile FOREIGN KEY(profile_id) REFERENCES accounting_exchange_profiles(id), CONSTRAINT fk_accounting_exchange_year FOREIGN KEY(fiscal_year_id) REFERENCES accounting_fiscal_years(id), CONSTRAINT fk_accounting_exchange_period FOREIGN KEY(period_id) REFERENCES accounting_periods(id), CONSTRAINT fk_accounting_exchange_journal FOREIGN KEY(journal_id) REFERENCES accounting_journals(id), CONSTRAINT fk_accounting_exchange_agency FOREIGN KEY(agency_id) REFERENCES agencies(id), CONSTRAINT fk_accounting_exchange_actor FOREIGN KEY(executed_by) REFERENCES users(id)
);

