INSERT INTO role_permissions(role_id,permission_id,scope) SELECT r.id,p.id,'GLOBAL' FROM roles r CROSS JOIN permissions p WHERE r.code='SUPER_ADMIN' AND r.is_system=TRUE AND r.is_active=TRUE AND p.code LIKE 'accounting.%' ON DUPLICATE KEY UPDATE scope=VALUES(scope);
